/**
 * prog #587 (#644): asset 0's creator pot is paid to its recorded payee (permissionless tag 90) before CloseSlab.
 * PDA / ATA / record vectors are the REAL crate's (prog rc23 2b5dce8a on engine 2f05df8c), copied from
 * percolator-sdk test/fixtures/creator-fee-payee-parity.json (generated by scripts/creator-fee-payee-parity/sdk_587_parity.rs).
 *
 * Run with: node --import tsx/esm --test src/cross-cluster/creator-fee-payee.test.ts
 */
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Keypair, PublicKey } from "@solana/web3.js";
import { parseAssetOracleProfileV17, parseWrapperConfigV17, deriveMarketVaultAccounts } from "@percolatorct/sdk";
import {
  P4_FLAG_CREATOR_FEE_PAYEE,
  buildPayeeClaimIxs,
  creatorRoute,
  decodePayeeRecord,
  deriveCreatorFeePayee,
  payeeDestination,
  readCreatorFeeState,
} from "./creator-fee-payee.ts";
import { assetSlotOffset, selectMarketGroupOffset } from "../wrapper-market-group-offset.ts";

const here = dirname(fileURLToPath(import.meta.url));
const fx = (n: string) => Buffer.from(readFileSync(join(here, "__fixtures__", `${n}.b64`), "utf8").trim(), "base64");

/** Crate vectors (see the header). */
const PROGRAM = new PublicKey("US517G5965aydkZ46HS38QLi7UQiSojurfbQfKCELFx"); // [7; 32]
const MARKET9 = new PublicKey("cGfHiC6Kgg3FpFZvgwGcswsCRtp4aBP2fzuXRQPizuN"); // [9; 32]
const GOOD_RECORD = "003631564352455013001300000000000909090909090909090909090909090909090909090909090909090909090909cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd020101ff00000000";

/** Rewrite asset 0's `asset_admin` / p4 byte / pots in a real market. */
function withCreator(src: Buffer, o: { admin?: Uint8Array; p4?: number; pot?: bigint; legacy?: bigint }): Buffer {
  const b = Buffer.from(src);
  const g = selectMarketGroupOffset(new Uint8Array(b));
  assert.ok(g.ok);
  const slot = assetSlotOffset(g, 0);
  if (o.admin) b.set(o.admin, slot + 368);
  if (o.p4 !== undefined) b[slot + 20] = o.p4;
  if (o.pot !== undefined) b.writeBigUInt64LE(o.pot, slot + 400);
  if (o.legacy !== undefined) b.writeBigUInt64LE(o.legacy, 16 + 568);
  return b;
}

describe("payee PDA / destination / record == the real crate", () => {
  it("PDA [creator_fee_payee, market, idx u16 LE]", () => {
    assert.deepEqual(deriveCreatorFeePayee(PROGRAM, MARKET9, 0).map(String), ["5Yxib62wQoTGyjPyEkBzjn2G6XPU4bU3mKb1VtZUYuZa", "254"]);
    assert.deepEqual(deriveCreatorFeePayee(PROGRAM, MARKET9, 256).map(String), ["EQCV1TT83tuyNjaJyAFEXk5yHonjtx7sxEr8VsVHtjAy", "255"]);
  });
  it("destination = canonical_vault_address(payee, mint), off-curve payees included", () => {
    const mint = new PublicKey("LbUiWL3xVV8hTFYBVdbTNrpDo41NKS6o3LHHuDzjfcY");
    assert.equal(payeeDestination(new PublicKey("CktRuQ2mttgRGkXJtyksdKHjUdc2C4TgDzyB98oEzy8"), mint).toBase58(), "GZdmt4xW34aAvtpEWiRZkLoT57FKy6gc2KU1oTSCNC8r");
    assert.equal(payeeDestination(new PublicKey("6MMiwDRfaY6Y7SL9j4JFnxudn4hcVY9asFKx1YnWcYUG"), mint).toBase58(), "9Z7jonrk3Vdou2FhGurbLSswm9HE8TQB7rEKVg9w7ZJ1");
  });
  it("decodes the real writer's record (asset 258) and refuses what the reader refuses", () => {
    const good = Buffer.from(GOOD_RECORD, "hex");
    assert.equal(decodePayeeRecord(good, MARKET9, 258)?.toBase58(), "ErNbLjU6E8tSbZH3REsMeTDP3Z8G52k6YedWwvBpAJ7v");
    assert.equal(decodePayeeRecord(good, MARKET9, 0), null, "another asset index");
    assert.equal(decodePayeeRecord(good, PROGRAM, 258), null, "another market");
    const reserved = Buffer.from(good); reserved[16 + 70] = 1;
    assert.equal(decodePayeeRecord(reserved, MARKET9, 258), null);
    const version = Buffer.from(good); version[16 + 66] = 2;
    assert.equal(decodePayeeRecord(version, MARKET9, 258), null);
    const kind = Buffer.from(good); kind[10] = 18;
    assert.equal(decodePayeeRecord(kind, MARKET9, 258), null);
    assert.equal(decodePayeeRecord(good.subarray(0, 87), MARKET9, 258), null);
  });
});

describe("route + market read", () => {
  const sol = fx("sol-market-v18-fees");
  it("claim_route", () => {
    assert.equal(creatorRoute(new Uint8Array(32).fill(1), 0), "AdminSigned");
    assert.equal(creatorRoute(new Uint8Array(32).fill(1), P4_FLAG_CREATOR_FEE_PAYEE), "AdminSigned");
    assert.equal(creatorRoute(new Uint8Array(32), P4_FLAG_CREATOR_FEE_PAYEE | 1), "Payee");
    assert.equal(creatorRoute(new Uint8Array(32), 0xf7), "Refused");
  });
  it("burned admin + bit 3 on a real market: route Payee, owed = asset-0 pot + legacy pot", () => {
    const m = withCreator(sol, { admin: new Uint8Array(32), p4: P4_FLAG_CREATOR_FEE_PAYEE, pot: 70n, legacy: 5n });
    const s = readCreatorFeeState(new Uint8Array(m));
    assert.ok(s);
    assert.equal(s.route, "Payee");
    assert.equal(s.owed, 75n);
    assert.equal(s.collateralMint.toBase58(), parseWrapperConfigV17(new Uint8Array(sol)).collateralMint.toBase58());
  });
  it("the real market as captured: live admin", () => {
    const s = readCreatorFeeState(new Uint8Array(sol));
    assert.equal(s?.route, "AdminSigned");
    const g = selectMarketGroupOffset(new Uint8Array(sol));
    assert.ok(g.ok);
    assert.ok(!parseAssetOracleProfileV17(new Uint8Array(sol), assetSlotOffset(g, 0)).assetAdmin.equals(PublicKey.default));
  });
});

describe("buildPayeeClaimIxs", () => {
  it("ATA create, then tag 90 with the payee ATA at [2] and the payee record at [6]", () => {
    const market = Keypair.generate().publicKey, caller = Keypair.generate().publicKey, payee = Keypair.generate().publicKey, mint = Keypair.generate().publicKey;
    const [create, t90] = buildPayeeClaimIxs({ programId: PROGRAM, market, caller, assetIndex: 0, payee, collateralMint: mint, amount: 42n, authorityEpoch: 3n });
    const dest = payeeDestination(payee, mint);
    assert.equal(create.programId.toBase58(), "ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL");
    assert.equal(create.keys[1].pubkey.toBase58(), dest.toBase58());
    assert.equal(create.keys[2].pubkey.toBase58(), payee.toBase58());
    const v = deriveMarketVaultAccounts(PROGRAM, market, mint);
    assert.deepEqual(t90.keys.map((k) => [k.pubkey.toBase58(), k.isSigner, k.isWritable]), [
      [caller.toBase58(), true, true], [market.toBase58(), false, true], [dest.toBase58(), false, true], [v.vaultToken.toBase58(), false, true],
      [v.vaultAuthority.toBase58(), false, false], ["TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA", false, false],
      [deriveCreatorFeePayee(PROGRAM, market, 0)[0].toBase58(), false, false],
    ]);
    // [90][amount u128][asset u16][epoch u64]
    assert.equal(Buffer.from(t90.data).toString("hex"), "5a" + "2a" + "00".repeat(15) + "0000" + "0300000000000000");
  });
});

// ── voff2 K1: never claim more than tag 90 can pay ──────────────────────────────────────────────
import { resolveMarketGeometry } from "@percolatorct/sdk";
import { creatorPayoutCap, payCreatorFeeToPayeeOnce } from "./creator-fee-payee.ts";
import { defaultDeps } from "./pre-resolve.ts";

function put128(b: Buffer, off: number, v: bigint): void { b.writeBigUInt64LE(v & ((1n << 64n) - 1n), off); b.writeBigUInt64LE(v >> 64n, off + 8); }
/** SOL v18 bytes with the engine pool fields set (insurance, reserved, budgets, engine vault). */
function withPool(src: Buffer, o: { insurance: bigint; reserved: bigint; budget: bigint; vault: bigint }): Buffer {
  const b = Buffer.from(src);
  const g = resolveMarketGeometry(new Uint8Array(b), { parser: "t", strictLength: false });
  put128(b, g.groupOff + g.layout.group.insurance, o.insurance);
  put128(b, g.groupOff + g.layout.group.sourceInsuranceCreditReservedTotalAtoms, o.reserved);
  put128(b, g.groupOff + g.layout.group.insuranceDomainBudgetRemainingTotal, o.budget);
  put128(b, g.groupOff + g.layout.group.vault, o.vault);
  return b;
}

describe("K1: creatorPayoutCap = the unbudgeted pool tag 90 / CloseSlab use, bounded by both vaults", () => {
  const sol = fx("sol-market-v18-fees");
  it("insurance - reserved - budget (no rent on a v18 market), then min with the engine and SPL vaults", () => {
    const m = new Uint8Array(withPool(sol, { insurance: 1_000n, reserved: 100n, budget: 600n, vault: 10_000n }));
    assert.equal(creatorPayoutCap(m, 10_000n), 300n);
    assert.equal(creatorPayoutCap(m, 250n), 250n, "SPL vault binds");
    const lowVault = new Uint8Array(withPool(sol, { insurance: 1_000n, reserved: 100n, budget: 600n, vault: 200n }));
    assert.equal(creatorPayoutCap(lowVault, 10_000n), 200n, "engine vault binds");
  });
  it("saturates at 0 when losses / budgets consumed the pool", () => {
    assert.equal(creatorPayoutCap(new Uint8Array(withPool(sol, { insurance: 500n, reserved: 100n, budget: 600n, vault: 10_000n })), 10_000n), 0n);
  });
});

describe("K1: payCreatorFeeToPayeeOnce claims min(owed, cap); skips without a tx at cap 0", () => {
  const sol = fx("sol-market-v18-fees");
  const keeper = Keypair.generate();
  const payee = Keypair.generate().publicKey;
  /** Burned admin + bit 3, pot 1,000 (legacy 0), and the given pool. */
  function market(pool: { insurance: bigint; reserved: bigint; budget: bigint; vault: bigint }): Buffer {
    return withCreator(withPool(sol, pool), { admin: new Uint8Array(32), p4: P4_FLAG_CREATOR_FEE_PAYEE, pot: 1_000n, legacy: 0n });
  }
  function conn(m: Buffer, mk: PublicKey, splVault: bigint) {
    const calls: string[] = [];
    let simulated: Buffer | null = null;
    const mint = parseWrapperConfigV17(new Uint8Array(m)).collateralMint;
    const vaultToken = deriveMarketVaultAccounts(PROGRAM, mk, mint).vaultToken;
    const rec = Buffer.alloc(88); rec.writeBigUInt64LE(0x5045_5243_5631_3600n, 0); rec.writeUInt16LE(19, 8); rec[10] = 19;
    mk.toBuffer().copy(rec, 16); payee.toBuffer().copy(rec, 48); rec[16 + 66] = 1;
    const tok = Buffer.alloc(165); tok.writeBigUInt64LE(splVault, 64);
    const c = {
      async getAccountInfo(pk: PublicKey) {
        calls.push("get");
        if (pk.equals(mk)) return { data: m, owner: PROGRAM };
        if (pk.equals(deriveCreatorFeePayee(PROGRAM, mk, 0)[0])) return { data: rec, owner: PROGRAM };
        if (pk.equals(vaultToken)) return { data: tok, owner: new PublicKey("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA") };
        return null;
      },
      async getLatestBlockhash() { calls.push("bh"); return { blockhash: "11111111111111111111111111111111", lastValidBlockHeight: 1 }; },
      async simulateTransaction(tx: { message: { compiledInstructions: Array<{ data: Uint8Array }> } }) {
        calls.push("sim");
        const ix = tx.message.compiledInstructions.find((i) => i.data[0] === 90 && i.data.length === 27);
        simulated = ix ? Buffer.from(ix.data) : null;
        return { value: { err: null, logs: [] } };
      },
      async sendRawTransaction() { calls.push("send"); return "sig"; },
    };
    return { c: c as never, calls, simulated: () => simulated };
  }
  const MK = Keypair.generate().publicKey;
  it("partly consumed pool: tag 90 asks for the cap (300), not the pot (1,000)", async () => {
    const k = conn(market({ insurance: 1_000n, reserved: 100n, budget: 600n, vault: 10_000n }), MK, 10_000n);
    const out = await payCreatorFeeToPayeeOnce(k.c, keeper, MK.toBase58(), true, undefined, PROGRAM);
    assert.equal(out, "skipped", JSON.stringify(out)); // dry run
    const d = k.simulated();
    assert.ok(d, "tag 90 simulated");
    assert.equal(d.readBigUInt64LE(1), 300n);
  });
  it("pool large enough: the whole pot (1,000)", async () => {
    const k = conn(market({ insurance: 1_000_000n, reserved: 0n, budget: 0n, vault: 1_000_000n }), MK, 1_000_000n);
    await payCreatorFeeToPayeeOnce(k.c, keeper, MK.toBase58(), true, undefined, PROGRAM);
    assert.equal(k.simulated()!.readBigUInt64LE(1), 1_000n);
  });
  it("pool 0: 'no-surplus', no simulation, no send (no spam)", async () => {
    const k = conn(market({ insurance: 500n, reserved: 100n, budget: 600n, vault: 10_000n }), MK, 10_000n);
    assert.equal(await payCreatorFeeToPayeeOnce(k.c, keeper, MK.toBase58(), false, undefined, PROGRAM), "no-surplus");
    assert.ok(!k.calls.includes("sim") && !k.calls.includes("send") && !k.calls.includes("bh"), k.calls.join());
  });
});

describe("the pre-resolve drain pays the payee by default", () => {
  it("defaultDeps.payCreator is payCreatorFeeToPayeeOnce", () => {
    assert.equal(defaultDeps.payCreator, payCreatorFeeToPayeeOnce);
  });
});

// ── prog #651: payee grace (7 x 216,000 slots after resolved_slot) ──────────────────────────────
import { CREATOR_PAYEE_GRACE_SLOTS, V22_GROUP_RESOLVED_SLOT_OFF, payeeGrace, payeeWindDownVerdict } from "./creator-fee-payee.ts";

describe("prog #651: payeeGrace + the Resolved wind-down verdict", () => {
  const v22 = fx("v22-sol-market-v19");
  function resolvedAt(slot: bigint, mode = 1): Uint8Array {
    const b = Buffer.from(v22);
    const g = resolveMarketGeometry(new Uint8Array(b), { parser: "t", strictLength: false });
    b[g.groupOff + g.layout.group.mode] = mode;
    b.writeBigUInt64LE(slot, g.groupOff + V22_GROUP_RESOLVED_SLOT_OFF);
    return new Uint8Array(b);
  }
  it("constants: 1,512,000 slots; resolved_slot right after mode (674) in the VERSION 19 group header", () => {
    assert.equal(CREATOR_PAYEE_GRACE_SLOTS, 7n * 216_000n);
    assert.equal(V22_GROUP_RESOLVED_SLOT_OFF, resolveMarketGeometry(new Uint8Array(v22), { parser: "t", strictLength: false }).layout.group.mode + 1);
  });
  it("boundary: end - 1 not over, end over; no slot / Live never; a VERSION 18 market has no payee grace (null)", () => {
    const d = resolvedAt(1_000n);
    const end = 1_000n + CREATOR_PAYEE_GRACE_SLOTS;
    assert.equal(payeeGrace(d, end - 1n)!.over, false);
    assert.equal(payeeGrace(d, end)!.over, true);
    assert.equal(payeeGrace(d, end)!.endSlot, end);
    assert.equal(payeeGrace(d, null)!.over, false);
    assert.equal(payeeGrace(resolvedAt(1_000n, 0), end + 5n)!.over, false);
    assert.equal(payeeGrace(new Uint8Array(fx("sol-market-v18-fees")), end), null);
  });
  it("verdict: success ok; failure inside the grace = rerun (exit 2); failure after the grace = re-bookable, not a blocker", () => {
    const d = resolvedAt(1_000n);
    const end = 1_000n + CREATOR_PAYEE_GRACE_SLOTS;
    assert.deepEqual(payeeWindDownVerdict("paid", payeeGrace(d, end), 5n), { ok: true, line: "paid" });
    const inside = payeeWindDownVerdict({ error: "Custom(136)" }, payeeGrace(d, end - 1n), 5n);
    assert.equal(inside.ok, false);
    assert.match(inside.line, new RegExp(`re-books the pot from slot ${end}`));
    const after = payeeWindDownVerdict({ error: "Custom(136)" }, payeeGrace(d, end), 5n);
    assert.equal(after.ok, true);
    assert.match(after.line, /5 atoms.*RE-BOOKABLE.*tag 84/);
    assert.equal(payeeWindDownVerdict({ error: "x" }, null, null).ok, false, "unknown grace: rerun");
  });
  it("the Resolved CLI path uses the verdict (not a bare 'payee failed = exit 2')", () => {
    const src = readFileSync(join(here, "..", "pre-resolve-drain.ts"), "utf8");
    assert.match(src, /const verdict = payeeWindDownVerdict\(payee, grace, owed\);/);
    assert.match(src, /const complete = w\.complete && verdict\.ok;/);
  });
});
